mapper.select:
select 
from houses_house h
join houses_city c on c.id = h.city_id
join houses_district d on d.id = h.district_id
where h.district_id = #{districtId}
  and h.id != #{excludeId}
order by h.crawl_time desc, h.id desc
limit #{limit}

select avg(h.unit_price)
from houses_house h
join houses_city c on c.id = h.city_id
join houses_district d on d.id = h.district_id
where c.name = #{city}
  and d.name = #{district}
